import json

# XM note encoding: note number (1 = C-0, MIDI offset)
# We'll use 1-based: C-4 = 49 (MIDI 60)
# MIDI 69 = A4, so MIDI - 12 = note number (1-based from C-0)
def midi_to_note(midi):
    return midi - 11  # 1-based: C-0 = 1

# Key: A minor (A B C D E F G)
# Chord progressions:
# Am - F - C - G (i - VI - III - VII)
# Am - C - Dm - E (i - III - iv - V)
# Dm - Am - Em - E (iv - i - ii - V)

# Tempo: 140 BPM, speed 6
# Each tick = 2.5/140 = 0.017857 sec, row = 6 ticks = 0.107 sec
# Pattern length: 64 rows = ~6.86 sec

# Channel assignments:
# Ch 0: Kick
# Ch 1: Bass
# Ch 2: Arp Lead (arpeggios)
# Ch 3: Square Lead (melody)
# Ch 4: Pad (chords)
# Ch 5: Noise (snare/hat)
# Ch 6: Tom fills
# Ch 7: Extra percussion/arp

NOTES = {
    'A2': 34, 'B2': 36, 'C3': 37, 'D3': 39, 'E3': 41, 'F3': 42, 'G3': 44,
    'A3': 46, 'B3': 48, 'C4': 49, 'D4': 51, 'E4': 53, 'F4': 54, 'G4': 56,
    'A4': 58, 'B4': 60, 'C5': 61, 'D5': 63, 'E5': 65, 'F5': 66, 'G5': 68,
    'A5': 70, 'Bb4': 59, 'Bb3': 47, 'C5s': 60,
}

# We need 8 patterns for variety
# Each pattern 64 rows

patterns_data = {}

# PATTERN 0: Intro - sparse, atmospheric
# Pad chords + occasional melody hint
def make_intro():
    cells = {}
    # Pad: Am chord (A3, C4, E4) holding
    am_notes = ['A3', 'C4', 'E4']
    for chord_notes in [['A3','C4','E4'], ['A3','C4','E4'], ['F3','A3','C4'], ['G3','B3','D4']]:
        pass  # will do it differently

    # Ch 4 (Pad): Am sustained for 16 rows, then F for 16, C for 16, G for 16
    chord_map = [
        (0, ['A3','C4','E4'], 16),
        (16, ['F3','A3','C4'], 16),
        (32, ['C4','E4','G4'], 16),
        (48, ['G3','B3','D4'], 16),
    ]

    for start, notes, dur in chord_map:
        inst = 3  # Pad
        cells[start, 4] = {'note': midi_to_note(NOTES[notes[0]]), 'instrument': inst, 'volume': 48}
        cells[start, 5] = {'note': midi_to_note(NOTES[notes[1]]), 'instrument': inst, 'volume': 48}
        cells[start, 6] = {'note': midi_to_note(NOTES[notes[2]]), 'instrument': inst, 'volume': 48}

    # Ch 3 (Square Lead): sparse melody notes
    melody_notes = [
        (0, 'A4'), (8, 'E4'), (16, 'C5'), (24, 'B4'),
        (32, 'G4'), (40, 'E4'), (48, 'D4'), (56, 'E4'),
    ]
    for row, note in melody_notes:
        cells[row, 3] = {'note': midi_to_note(NOTES[note]), 'instrument': 1, 'volume': 44}

    return cells

# PATTERN 1: Build-up - add bass and rhythm
def make_buildup():
    cells = {}

    # Pad chords
    chord_map = [
        (0, ['D3','F3','A3'], 16),  # Dm
        (16, ['A3','C4','E4'], 16),  # Am
        (32, ['E3','G3','B3'], 16),  # Em
        (48, ['E3','G#3','B3'], 16),  # E (major - tension)
    ]
    # G# is not in our notes dict, handle specially
    chord_map_fixed = [
        (0, ['D3','F3','A3'], 16),
        (16, ['A3','C4','E4'], 16),
        (32, ['E3','G3','B3'], 16),
        (48, ['E3', 56, 'B3'], 16),  # G3=44, G#3 would be 45, but we don't have it
    ]

    for start, notes, dur in chord_map_fixed:
        inst = 3
        for ci, n in enumerate(notes):
            nv = midi_to_note(NOTES[n]) if isinstance(n, str) else midi_to_note(n)
            cells[start, 4+ci] = {'note': nv, 'instrument': inst, 'volume': 44}

    # Bass: root notes on beat
    bass_map = [
        (0, 'D3'), (4, 'D3'), (8, 'D3'), (12, 'D3'),
        (16, 'A3'), (20, 'A3'), (24, 'A3'), (28, 'A3'),
        (32, 'E3'), (36, 'E3'), (40, 'E3'), (44, 'E3'),
        (48, 'E3'), (52, 'E3'), (56, 'E3'), (60, 'E3'),
    ]
    for row, note in bass_map:
        cells[row, 1] = {'note': midi_to_note(NOTES[note]), 'instrument': 2, 'volume': 52}

    # Kick on beats 0, 4, 8, etc.
    for row in range(0, 64, 4):
        cells[row, 0] = {'note': midi_to_note(NOTES['A2']), 'instrument': 5, 'volume': 56}

    # Snare on 4 and 12 of each group
    for row in [4, 12, 20, 28, 36, 44, 52, 60]:
        cells[row, 7] = {'note': midi_to_note(NOTES['C4']), 'instrument': 4, 'volume': 40}

    # Melody
    melody_notes = [
        (0, 'A4'), (2, 'B4'), (4, 'C5'), (6, 'D5'),
        (8, 'E5'), (10, 'D5'), (12, 'C5'), (14, 'B4'),
        (16, 'A4'), (20, 'C5'), (24, 'E5'), (28, 'D5'),
        (32, 'B4'), (36, 'G4'), (40, 'E4'), (44, 'G4'),
        (48, 'G#4'), (50, 'B4'), (54, 'E5'), (58, 'D5'),
    ]
    for row, note in melody_notes:
        cells[row, 3] = {'note': midi_to_note(NOTES[note]) if note in NOTES else 57, 'instrument': 1, 'volume': 44}

    return cells

# PATTERN 2: Main groove A
def make_main_a():
    cells = {}

    # Pad: Am - F - C - G progression
    chord_map = [
        (0, ['A3','C4','E4'], 16),
        (16, ['F3','A3','C4'], 16),
        (32, ['C4','E4','G4'], 16),
        (48, ['G3','B3','D4'], 16),
    ]

    for start, notes, dur in chord_map:
        inst = 3
        for ci, n in enumerate(notes):
            cells[start, 4+ci] = {'note': midi_to_note(NOTES[n]), 'instrument': inst, 'volume': 40}

    # Bass: walking pattern
    bass_chords = [
        (0, ['A2', 'E3', 'A3', 'E3']),  # Am
        (16, ['F3', 'C4', 'F3', 'C4']),  # F
        (32, ['C4', 'G4', 'C5', 'G4']),  # C
        (48, ['G3', 'D4', 'G3', 'D4']),  # G
    ]

    for start, notes in bass_chords:
        for i, n in enumerate(notes):
            cells[start + i*4, 1] = {'note': midi_to_note(NOTES[n]), 'instrument': 2, 'volume': 52}

    # Kick on every beat (every 4 rows)
    for row in range(0, 64, 4):
        cells[row, 0] = {'note': midi_to_note(NOTES['A2']), 'instrument': 5, 'volume': 56}

    # Snare/hat on offbeats
    for row in [4, 12, 20, 28, 36, 44, 52, 60]:
        cells[row, 5] = {'note': midi_to_note(NOTES['C4']), 'instrument': 4, 'volume': 36}
    for row in [2, 6, 10, 14, 18, 22, 26, 30, 34, 38, 42, 46, 50, 54, 58, 62]:
        cells[row, 5] = {'note': midi_to_note(NOTES['C4']), 'instrument': 4, 'volume': 24}

    # Arpeggio pattern: fast arps
    arp_notes = [
        (0, 'A3'), (1, 'C4'), (2, 'E4'), (3, 'C4'),
        (4, 'A3'), (5, 'C4'), (6, 'E4'), (7, 'C4'),
        (8, 'A3'), (9, 'C4'), (10, 'E4'), (11, 'C4'),
        (12, 'A3'), (13, 'C4'), (14, 'E4'), (15, 'C4'),
        (16, 'F3'), (17, 'A3'), (18, 'C4'), (19, 'A3'),
        (20, 'F3'), (21, 'A3'), (22, 'C4'), (23, 'A3'),
        (24, 'F3'), (25, 'A3'), (26, 'C4'), (27, 'A3'),
        (28, 'F3'), (29, 'A3'), (30, 'C4'), (31, 'A3'),
        (32, 'C4'), (33, 'E4'), (34, 'G4'), (35, 'E4'),
        (36, 'C4'), (37, 'E4'), (38, 'G4'), (39, 'E4'),
        (40, 'C4'), (41, 'E4'), (42, 'G4'), (43, 'E4'),
        (44, 'C4'), (45, 'E4'), (46, 'G4'), (47, 'E4'),
        (48, 'G3'), (49, 'B3'), (50, 'D4'), (51, 'B3'),
        (52, 'G3'), (53, 'B3'), (54, 'D4'), (55, 'B3'),
        (56, 'G3'), (57, 'B3'), (58, 'D4'), (59, 'B3'),
        (60, 'G3'), (61, 'B3'), (62, 'D4'), (63, 'B3'),
    ]
    for row, note in arp_notes:
        cells[row, 2] = {'note': midi_to_note(NOTES[note]), 'instrument': 6, 'volume': 42}

    # Melody
    melody = [
        (0, 'E5'), (4, 'E5'), (8, 'D5'), (12, 'C5'),
        (16, 'A4'), (20, 'A4'), (24, 'C5'), (28, 'D5'),
        (32, 'E5'), (36, 'E5'), (40, 'D5'), (44, 'C5'),
        (48, 'B4'), (52, 'B4'), (56, 'C5'), (60, 'B4'),
    ]
    for row, note in melody:
        cells[row, 3] = {'note': midi_to_note(NOTES[note]), 'instrument': 1, 'volume': 48}

    return cells

# PATTERN 3: Main groove B (variation)
def make_main_b():
    cells = {}

    # Pad: Dm - Am - Em - E
    chord_map = [
        (0, ['D3','F3','A3'], 16),
        (16, ['A3','C4','E4'], 16),
        (32, ['E3','G3','B3'], 16),
        (48, ['E3', 56, 'B3'], 16),  # E major (G3 = 44, so midi_to_note(44) = G3)
    ]

