import sys, json, struct, base64

lines = sys.stdin.read().strip().split('\n')
print(f"Total lines: {len(lines)}")

# Extract all cell data
patterns = {}
for line in lines:
    try:
        data = json.loads(line)
        text = json.loads(data['content'][0]['text'])
        pat = text['pattern']
        row = text['row']
        ch = text['channel']
        if pat not in patterns:
            patterns[pat] = {}
        if row not in patterns[pat]:
            patterns[pat][row] = {}
        patterns[pat][row][ch] = text
    except:
        pass

print(f"Patterns found: {sorted(patterns.keys())}")
for p in sorted(patterns.keys()):
    rows = patterns[p]
    nonempty = sum(1 for r in rows for c in rows[r] if rows[r][c]['note'] > 0 or rows[r][c]['instrument'] > 0)
    print(f"  Pattern {p}: {len(rows)} rows with data, {nonempty} non-empty cells")
